import pandas as pd

files = ['DanhSachNhapHang.xlsx','DanhSachHoaDon.xlsx','DanhSachDonViTinh.xlsx','SoQuy.xlsx']
for f in files:
    for i, sheet in enumerate(pd.ExcelFile(f, engine='openpyxl').sheet_names):
        d = pd.read_excel(f, sheet_name=sheet)
        cols = [c for c in d.columns if any(k in c for k in ['Hạn','HSD','expiration','exp','Nhập ngày','ngày','Date'])]
        if cols:
            print(f"{f} [{sheet}] exp/date cols: {cols}")
            print("  sample:", d[cols].head(2).to_string())
        if any(k in ' '.join(d.columns).lower() for k in ['hạn','hsd','exp','expiry','lot',' lô','nhập ngày']):
            print(f"  MATCH columns found above")

